// DeleteUniqueIndexCache 删除索引存在的缓存
func (u *UserMessageRepo) DeleteIndexCache(ctx context.Context, data ...*ai_boilerplate_model.UserMessage) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, u.cache.Key(CacheUserMessageByConditionPrefix))
	keys = append(keys, u.cache.Key(CacheUserMessageUnscopedByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[u.cache.Key(CacheUserMessageByIDPrefix, item.ID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMessageUnscopedByIDPrefix, item.ID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMessageByMessageIDPrefix, item.MessageID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMessageUnscopedByMessageIDPrefix, item.MessageID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMessageByUserIDCategoryPrefix, item.UserID, item.Category)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMessageUnscopedByUserIDCategoryPrefix, item.UserID, item.Category)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMessageByUserIDPrefix, item.UserID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserMessageUnscopedByUserIDPrefix, item.UserID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := u.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
